using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.JNT.JuntaDetalle;using GraphApi.Services.JNT.JuntaDetalle;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.JNT.JuntaDetalle{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de JuntaDetalles: creación, actualización y eliminación.")]    public class JuntaDetalleMutation    {        [Authorize]        [GraphQLName("createJuntaDetalle")]        [GraphQLDescription("Crea un nuevo JuntaDetalle usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadJuntaDetalle> CreateJuntaDetalleAsync(            [GraphQLDescription("Datos necesarios para crear el JuntaDetalle.")]            clCreateJuntaDetalle objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de JuntaDetalle.")]            IJuntaDetalleService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateJuntaDetalle(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateJuntaDetalle")]        [GraphQLDescription("Actualiza los campos especificados de un JuntaDetalle existente.")]        public async Task<clReadJuntaDetalle?> UpdateJuntaDetalleAsync(            [GraphQLDescription("Datos del JuntaDetalle a actualizar.")]            clUpdateJuntaDetalle objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de JuntaDetalle.")]            IJuntaDetalleService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateJuntaDetalle(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteJuntaDetalle")]        [GraphQLDescription("Elimina un JuntaDetalle por su ID.")]        public async Task<bool> delJuntaDetalleAsync(            [GraphQLDescription("ID del JuntaDetalle a eliminar.")]            int nJuntaDetalleID,            [Service]            [GraphQLDescription("Servicio para operaciones de JuntaDetalle.")]            IJuntaDetalleService objService        )        {            return await objService.DeleteJuntaDetalle(nJuntaDetalleID);        }    }}